const CHAPTERS=[{"id":"permit","name":"Permits & Licensing","icon":"🪪","src":"Handbook: Driver Education & Permits","qs":[{"id":"per-1gzug3d","q":"What is the minimum age to get a Utah entry-level learner permit?","a":"15","o":["15","14","16","17"],"why":"Utah's entry-level learner permit starts at age 15. The 6-month learner permit starts at 16."},{"id":"per-1rubvg5","q":"A 16 or 17 year old needs to hold a learner permit for how long before getting a license?","a":"At least six months","o":["At least six months","At least 90 days","At least twelve months","At least thirty days"],"why":"Ages 16 and 17 must hold the permit six months and finish driver education."},{"id":"per-1c8b9qg","q":"Utah teens ages 15 to 18 must drive how many hours with a parent or guardian before licensing?","a":"40 hours, with 10 after sunset","o":["40 hours, with 10 after sunset","40 hours, with 20 after sunset","50 hours, with 10 after sunset","30 hours, with 10 after sunset"],"why":"The handbook requires 40 hours of driving, 10 of them after sunset."},{"id":"per-ivaaw9","q":"Which of these may supervise a minor learner permit driver under the 2026 change in the law?","a":"A licensed stepparent or foster parent","o":["A licensed stepparent or foster parent","A licensed older sibling who is 18","Any licensed friend who is 18","A licensed neighbor with no written permission"],"why":"SB 22 (2026) lets a stepparent or foster parent supervise a minor permit holder."},{"id":"per-18dqal5","q":"How must the learner permit be carried while you drive?","a":"In your immediate possession","o":["In your immediate possession","Stored in the trunk of the car","Left at home with a parent","Carried only when driving at night"],"why":"The permit must be in your immediate possession whenever you drive."},{"id":"per-13ij65x","q":"What does a Utah provisional license tell you about the holder?","a":"The driver is under 21","o":["The driver is under 21","The driver is new to Utah","The driver is under 18","The driver failed the first road test"],"why":"A provisional license is issued to every Utah driver under age 21."},{"id":"per-1pygyvk","q":"What is the minimum age for an original regular Utah Class D license?","a":"16","o":["16","15","17","18"],"why":"Class D, the regular car license, has a minimum age of 16."},{"id":"per-ir1der","q":"Which license class covers a regular passenger car?","a":"Class D","o":["Class D","Class A","Class B","Class C"],"why":"Class D covers vehicles that are not Class A, B, C, or a motorcycle."},{"id":"per-1qb5lhb","q":"A 19 year old with no license and no driver education must hold a learner permit for how long?","a":"90 days","o":["90 days","6 months","30 days","1 year"],"why":"Age 19 and older can skip driver education by holding the permit 90 days and logging 40 hours."},{"id":"per-huiyvm","q":"A first-time applicant who is 18 must do what?","a":"Finish an approved driver education course","o":["Finish an approved driver education course","Hold a permit for six full months","Hold a permit for at least 90 days","Pass a second written knowledge test"],"why":"At 18 there is no holding period, but driver education is required."},{"id":"per-100brcq","q":"How many behind-the-wheel hours are part of a Utah driver education course?","a":"6 hours","o":["6 hours","10 hours","4 hours","12 hours"],"why":"The course includes 6 hours behind the wheel plus classroom and observation time."},{"id":"per-1ib3fe","q":"Which endorsement lets you ride a motorcycle?","a":"M","o":["M","H","S","T"],"why":"The M endorsement covers motorcycles."},{"id":"per-1se74e4","q":"A 16 year old with a full license may not drive during which hours without a licensed adult 21 or older?","a":"12:00 a.m. to 5:00 a.m.","o":["12:00 a.m. to 5:00 a.m.","10:00 p.m. to 5:00 a.m.","11:00 p.m. to 6:00 a.m.","9:00 p.m. to 4:00 a.m."],"why":"Age 16 drivers have a midnight to 5 a.m. limit, with exceptions like work, school events, and emergencies."},{"id":"per-1cd7rso","q":"For the first six months, a licensed 16 year old may carry passengers who are:","a":"Immediate family only","o":["Immediate family only","Any friends","Anyone age 21 or younger","Anyone with written permission"],"why":"The passenger limit is immediate family until six months after the license is issued, with exceptions."},{"id":"per-58wl8o","q":"A visitor has a valid license from another state and is at least 16. In Utah, they may:","a":"Drive without a Utah license","o":["Drive without a Utah license","Drive only with a Utah permit","Drive only for 30 days","Drive only with a Utah driver in the car"],"why":"Out-of-state licensed drivers 16 and older may drive in Utah."},{"id":"per-1j0ekyg","q":"How soon must a Class D driver tell the division after moving to a new address?","a":"Within 10 days","o":["Within 10 days","Within 30 days","Within 90 days","At the next renewal"],"why":"Class D drivers notify the division within 10 days of an address change."}]},{"id":"tests","name":"Tests & Paperwork","icon":"📝","src":"Handbook: Examinations","qs":[{"id":"tes-1a6nw4g","q":"What score do you need to pass the Utah written knowledge test?","a":"80% or better","o":["80% or better","70% or better","75% or better","90% or better"],"why":"The written test passing score is 80% or better."},{"id":"tes-qp3yzd","q":"How long is a passing written test score valid for an entry-level permit?","a":"18 months","o":["18 months","6 months","12 months","24 months"],"why":"A passing score stays valid 18 months for the entry-level permit."},{"id":"tes-14zfckv","q":"How is the written knowledge test timed?","a":"It is untimed","o":["It is untimed","30 minutes total","60 minutes total","15 minutes total"],"why":"The test is untimed. Most people take 30 to 45 minutes."},{"id":"tes-azm09c","q":"The written test fee covers how many attempts within 12 months?","a":"Up to three","o":["Up to three","Just one","Up to two","Unlimited"],"why":"The fee covers up to three attempts in 12 months. Three more need another fee."},{"id":"tes-q8t8j9","q":"What score is required on the online Traffic Safety and Trends Exam?","a":"100%","o":["100%","80%","70%","90%"],"why":"First-time Class D applicants must score 100%, and they may retake it as needed."},{"id":"tes-11m2n0z","q":"Who may be in the car during the driving skills test?","a":"Only you and the examiner","o":["Only you and the examiner","You, the examiner, and a parent","You and a friend","You, the examiner, and your instructor"],"why":"Only the applicant and the examiner ride along."},{"id":"tes-1q9dkzu","q":"Who provides the vehicle for the driving skills test?","a":"The applicant","o":["The applicant","The testing office","The examiner","A rental service"],"why":"You bring a registered, clean, safe vehicle."},{"id":"tes-un4z63","q":"Which of these is NOT required on a skills test vehicle?","a":"A front license plate","o":["A front license plate","A working horn","Working brake lights","Working safety belts"],"why":"The front plate is not required after January 1, 2025. The rest still are."},{"id":"tes-1fys8az","q":"Which of these will automatically fail a skills test?","a":"Failing to yield to a pedestrian","o":["Failing to yield to a pedestrian","Asking the examiner to repeat a direction","Checking mirrors before a lane change","Adjusting your seat before you start"],"why":"Failing to yield to others is an automatic fail, along with speeding, rolling stops, and avoidable crashes."},{"id":"tes-1e1vbvh","q":"What must you bring to the skills test besides your permit?","a":"Valid registration and insurance for the vehicle","o":["Valid registration and insurance for the vehicle","Your school transcript and test receipt","A copy of your birth certificate again","A written note from your parent"],"why":"Bring your permit, valid registration, and valid insurance."},{"id":"tes-10iew1c","q":"How many driving skills tests can you take in one day?","a":"One","o":["One","Two","Three","As many as you need"],"why":"Only one skills test per day is allowed."},{"id":"tes-1mgl3he","q":"Tests must be completed within how long after paying the test fee?","a":"Six months","o":["Six months","Three months","One year","Eighteen months"],"why":"All tests must be finished within six months of paying."},{"id":"tes-1tybij1","q":"Which driver assist features may NOT be used during the skills test?","a":"Parking assist and cruise control","o":["Parking assist and cruise control","Turn signals and side mirrors","Headlights and the horn","Wipers and the defroster"],"why":"Parking assist and cruise control are not allowed on the skills test."},{"id":"tes-wuu8wz","q":"The Utah Class D vision standard requires acuity of at least:","a":"20/40 in at least one eye","o":["20/40 in at least one eye","20/20 in each of your eyes","20/30 in at least one eye","20/60 in at least one eye"],"why":"Class D needs 20/40 in at least one eye and a 90 degree visual field."}]},{"id":"ready","name":"Get Ready to Drive","icon":"💺","src":"Handbook: Preparing Your Vehicle","qs":[{"id":"rea-hhwgzq","q":"Who in the car must wear a fastened safety belt or ride in a child seat?","a":"Everyone in the vehicle","o":["Everyone in the vehicle","Only the driver","The driver and front passenger","Anyone under 16"],"why":"Utah requires everyone to be belted or in a child seat."},{"id":"rea-1alby34","q":"How much space should you leave between your chest and the steering wheel?","a":"About 10 inches","o":["About 10 inches","About 4 inches","About 6 inches","About 15 inches"],"why":"Leave 10 inches so the air bag can inflate safely."},{"id":"rea-6291m3","q":"Where should the lap belt sit?","a":"Across your hips, not your stomach","o":["Across your hips, not your stomach","Across your stomach and ribs","Across your lower chest","Across your stomach, above the hips"],"why":"A lap belt crosses the hips. A belt on the stomach can injure organs."},{"id":"rea-1te3bqx","q":"Where should the shoulder belt cross your body?","a":"Over your shoulder and chest","o":["Over your shoulder and chest","Under your arm and across the ribs","Behind your back and across the lap","Across your neck and upper chest"],"why":"Never wear it under the arm or behind the back."},{"id":"rea-pk6rjv","q":"Children age 8 and under need an approved child seat unless they are how tall?","a":"57 inches","o":["57 inches","48 inches","52 inches","60 inches"],"why":"Children age 8 and under need a seat until they are 57 inches tall."},{"id":"rea-14g6jds","q":"How long should a child ride rear-facing, if the seat allows?","a":"Until at least age 2 and 30 pounds","o":["Until at least age 2 and 30 pounds","Until at least age 1 and 20 pounds","Until at least age 3 and 40 pounds","Until 6 months"],"why":"The handbook says rear-facing until at least age two and 30 pounds."},{"id":"rea-1h1p9tj","q":"A forward-facing child seat with a harness is used until at least:","a":"Age 4 and 40 pounds","o":["Age 4 and 40 pounds","Age 2 and 25 pounds","Age 6 and 60 pounds","Age 3 and 30 pounds"],"why":"After rear-facing, use a harness seat until at least age four and 40 pounds."},{"id":"rea-o0wwa9","q":"Where should children 12 and under ride?","a":"Buckled in a rear seat","o":["Buckled in a rear seat","In the front with a belt","In the front if they are tall","On an adult's lap"],"why":"Children 12 and under belong in the back seat."},{"id":"rea-h1fpgc","q":"Which is never safe for an infant?","a":"Riding in front of a passenger-side air bag","o":["Riding in front of a passenger-side air bag","Riding in an approved rear-facing seat","Riding in the middle of the back seat","Riding buckled in a rear passenger seat"],"why":"Infants should never ride in front of a passenger-side air bag."},{"id":"rea-13ezibj","q":"Where should the head restraint touch your head?","a":"The back of your head, above ear level","o":["The back of your head, above ear level","The base of your neck only","The middle of your upper back","Just below your ear level"],"why":"Set it so it contacts the back of the head above ear level."},{"id":"rea-14ks7ba","q":"How should you set your outside mirrors?","a":"To cut blind spots and show adjacent lanes","o":["To cut blind spots and show adjacent lanes","To show the side of your own car","To show only the road behind you","To point down toward the pavement"],"why":"Set them wide to minimize blind spots."},{"id":"rea-e2itau","q":"Smoking in a car with a passenger 15 or younger is:","a":"An infraction","o":["An infraction","Fine with a window open","Fine if a parent is driving","A felony"],"why":"Smoking while transporting a child 15 or younger is an infraction in Utah."},{"id":"rea-l80hpt","q":"Which type of vehicle is exempt from the belt law?","a":"A school bus","o":["A school bus","A pickup truck","A minivan","A taxi"],"why":"Exempt vehicles include school buses, motorcycles, mopeds, authorized emergency vehicles, and vehicles built without belts."}]},{"id":"basic","name":"Basic Driving","icon":"🛞","src":"Handbook: Basic Driving","qs":[{"id":"bas-114bjt","q":"Where must you never back up?","a":"On a freeway or interstate","o":["On a freeway or interstate","In a private driveway","In a shopping center lot","On a quiet residential street"],"why":"The handbook says never back on a freeway or interstate."},{"id":"bas-1214bia","q":"When backing, how should you check behind you?","a":"Look through the rear window","o":["Look through the rear window","Use only the side mirrors","Use only the dashboard camera","Watch only the curb"],"why":"Mirrors do not show the area right behind the car."},{"id":"bas-wengrw","q":"When backing, which way should you steer?","a":"The way you want the back of the car to go","o":["The way you want the back of the car to go","The opposite way you want the back to go","Toward the curb at all times","Always to the left side first"],"why":"Steer in the direction you want the rear to move."},{"id":"bas-62v5q2","q":"How long should you signal before a lane change?","a":"At least two seconds","o":["At least two seconds","About one second","Only when a car is nearby","Until the lane change is half done"],"why":"Signal at least two seconds before moving, then head check."},{"id":"bas-o629up","q":"Before changing lanes you should always:","a":"Check mirrors and do a head check","o":["Check mirrors and do a head check","Tap your horn to alert drivers","Brake lightly to slow traffic","Flash your high beams twice"],"why":"Check mirrors, signal, and look over your shoulder."},{"id":"bas-hb0cav","q":"Changing lanes in the middle of an intersection is:","a":"Not allowed","o":["Not allowed","Fine if the lane is clear","Fine on a green light","Fine at night"],"why":"Do not change lanes in an intersection."},{"id":"bas-1e5ea02","q":"On a multi-lane road, which lane should you normally use?","a":"The far right lane, unless passing or blocked","o":["The far right lane, unless passing or blocked","The far left lane, to keep up","Whichever lane seems the fastest","The center lane, to avoid merging cars"],"why":"Stay right unless you are passing or the lane is blocked."},{"id":"bas-se6kw1","q":"At a zipper merge, you should:","a":"Use both lanes, then alternate at the merge point","o":["Use both lanes, then alternate at the merge point","Merge into one lane as early as you can","Speed up to get ahead of the other lane","Stop at the merge and wait for a gap"],"why":"With a zipper merge, drivers alternate at the merge point."},{"id":"bas-4la8wi","q":"When you park at a curb, how close should your wheels be?","a":"Within 12 inches","o":["Within 12 inches","Within 24 inches","Within 6 inches","Within 18 inches"],"why":"Park as close as possible, within 12 inches of the curb."},{"id":"bas-1mo4ubm","q":"How close to a fire hydrant may you park?","a":"No closer than 15 feet","o":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","No closer than 25 feet"],"why":"Keep 15 feet clear of a hydrant."},{"id":"bas-1z12e0b","q":"How close to a crosswalk may you park?","a":"No closer than 20 feet","o":["No closer than 20 feet","No closer than 10 feet","No closer than 15 feet","No closer than 5 feet"],"why":"Stay at least 20 feet back from a crosswalk."},{"id":"bas-1vifrti","q":"How close to the rail at a railroad crossing may you park?","a":"No closer than 50 feet","o":["No closer than 50 feet","No closer than 25 feet","No closer than 15 feet","No closer than 100 feet"],"why":"Do not park within 50 feet of a crossing unless signs allow it."},{"id":"bas-ppz40l","q":"When parking downhill next to a curb, turn your wheels:","a":"Toward the curb","o":["Toward the curb","Away from the curb","Straight ahead","Toward the road"],"why":"Downhill, wheels turn toward the curb so the car rolls into it."},{"id":"bas-avlzg4","q":"When parking uphill next to a curb, turn your wheels:","a":"Away from the curb","o":["Away from the curb","Toward the curb","Straight ahead","It does not matter"],"why":"Uphill, wheels turn away from the curb."},{"id":"bas-1rxnv64","q":"After passing, you may return to the right lane no less than how far from an oncoming vehicle?","a":"200 feet","o":["200 feet","50 feet","100 feet","500 feet"],"why":"Return to the right lane at least 200 feet ahead of oncoming traffic."},{"id":"bas-k6ie46","q":"Which of these is a place where you must not pass?","a":"Before a railroad crossing or bridge","o":["Before a railroad crossing or bridge","On a straight road with a clear view","In the left lane of a multi-lane road","On a road with a broken yellow line on your side"],"why":"Never pass before a railroad crossing or bridge, at intersections, or where view is blocked."},{"id":"bas-dg8oos","q":"Where should your hands be on the steering wheel?","a":"On the outside of the wheel","o":["On the outside of the wheel","At the very top of the wheel","One hand on the inside spokes","Anywhere that feels comfortable"],"why":"Keep both hands on the outside of the wheel."},{"id":"bas-aebhe3","q":"What following distance does the handbook give for normal conditions?","a":"At least two seconds","o":["At least two seconds","One second","Four car lengths exactly","Ten seconds"],"why":"Use a two-second gap, and more in bad weather."},{"id":"bas-99zrks","q":"When stopped behind another car, you should be able to see:","a":"The bottom of its rear tires","o":["The bottom of its rear tires","Only its rear bumper","Only its license plate","Only the top of its trunk"],"why":"Seeing its rear tires leaves room to pull around."},{"id":"bas-1y36fzr","q":"Where is a U-turn never allowed?","a":"On a freeway","o":["On a freeway","On a wide quiet street with no sign","At a signal with no sign forbidding it","From the left lane of a wide street"],"why":"U-turns are illegal on a freeway, on railroad tracks, and where signs forbid them."}]},{"id":"signs","name":"Road Signs","icon":"🛑","src":"Handbook: Signs","qs":[{"id":"sig-tlcf1r","q":"What does this sign mean?","a":"Come to a full stop, then go when it is safe","o":["Come to a full stop, then go when it is safe","Slow down and go if no one is coming","Stop only if other cars are present","Stop and wait for the flagger to wave"],"why":"A STOP sign always means a complete stop, then yield where required.","vis":"stop"},{"id":"sig-9h8sk0","q":"What should you do at this sign?","a":"Slow down and let other traffic go first","o":["Slow down and let other traffic go first","Come to a full stop every single time","Speed up to merge ahead of other traffic","Stop only if a pedestrian is crossing"],"why":"A YIELD sign means slow down and let traffic with the right-of-way go first.","vis":"yield"},{"id":"sig-1lfqs59","q":"This sign tells you:","a":"The maximum legal speed is 25 mph","o":["The maximum legal speed is 25 mph","The minimum legal speed is 25 mph","The suggested speed is 25 mph","The speed limit changes in 25 miles"],"why":"A speed limit sign shows the highest legal speed in good conditions.","vis":"speed25"},{"id":"sig-q9x6d8","q":"This round yellow sign means:","a":"A railroad crossing is ahead; slow and look","o":["A railroad crossing is ahead; slow and look","A rail passenger station is ahead","A roundabout is coming up ahead","A truck crossing is coming up ahead"],"why":"The round yellow RR sign warns that a crossing is ahead. Be ready to stop.","vis":"rr"},{"id":"sig-vchlo","q":"This white X sign at a crossing means:","a":"A railroad crossing; yield to any train","o":["A railroad crossing; yield to any train","Road closed to all traffic ahead","A railroad museum is just ahead","No parking within 50 feet of the tracks"],"why":"A crossbuck marks a railroad crossing. Yield to trains.","vis":"crossbuck"},{"id":"sig-1ux0q30","q":"This five-sided sign means:","a":"A school zone or school crossing is near","o":["A school zone or school crossing is near","A playground with no school nearby","A school bus stop is just ahead","A hospital zone with quiet hours"],"why":"A pentagon sign warns of a school zone or crossing.","vis":"school"},{"id":"sig-9nhvc3","q":"This sign means:","a":"Do not enter","o":["Do not enter","No parking","One way street","Road closed for the season"],"why":"A red circle with a white bar means you may not enter. You would be going the wrong way.","vis":"dne"},{"id":"sig-t2arsh","q":"You see this sign. What does it tell you?","a":"You are driving against traffic","o":["You are driving against traffic","You are in the wrong lane to turn","You are in a no-passing zone","A detour is ahead"],"why":"WRONG WAY warns you are heading the wrong direction. Stop and turn around safely.","vis":"wrongway"},{"id":"sig-w0next","q":"This sign means:","a":"Traffic moves only the way the arrow points","o":["Traffic moves only the way the arrow points","Two-way traffic is coming up ahead","The detour route leads this way","Only right turns are allowed here"],"why":"ONE WAY means traffic flows only the way the arrow points. Never drive against it.","vis":"oneway"},{"id":"sig-xlxfgz","q":"This sign means:","a":"U-turns are not allowed","o":["U-turns are not allowed","Left turns are not allowed","The road ends ahead","You must turn around"],"why":"A red circle with a slash cancels the picture inside it. This sign bans U-turns.","vis":"nouturn"},{"id":"sig-1s0b41t","q":"Orange signs like this one tell you:","a":"You are near a work zone: slow down","o":["You are near a work zone: slow down","A detour route for farm vehicles","A temporary emergency road closure","A park or picnic area ahead"],"why":"Orange signs mark work zones. Slow down even if no workers are in sight.","vis":"roadwork"},{"id":"sig-1mena9k","q":"This yellow diamond warns of:","a":"Pedestrians crossing ahead","o":["Pedestrians crossing ahead","A school bus stop ahead","A sidewalk that is ending","A hiking trail crossing"],"why":"Yellow diamonds warn about conditions ahead. This one warns people may be crossing.","vis":"ped"},{"id":"sig-1k64chx","q":"This blue sign tells you:","a":"A hospital is nearby","o":["A hospital is nearby","A rest area is ahead","A helicopter pad is ahead","Handicap parking only"],"why":"Blue signs give services. A white H on blue marks a hospital.","vis":"hospital"},{"id":"sig-12v7mh8","q":"This shield tells you what kind of road?","a":"An interstate highway","o":["An interstate highway","A Utah state route","A U.S. highway route","A county or city road"],"why":"The red, white, and blue shield marks an interstate.","vis":"shield"},{"id":"sig-zgz66p","q":"What shape and color are warning signs?","a":"Yellow diamonds","o":["Yellow diamonds","Red octagons","White rectangles","Green squares"],"why":"Warning signs are yellow diamonds with black symbols or words."},{"id":"sig-rrezky","q":"What color are work zone signs?","a":"Orange with black","o":["Orange with black","Yellow with red","Red with white","Green with white"],"why":"Work zone signs are orange with black lettering."},{"id":"sig-t4cao8","q":"What does a red circle with a slash through a picture mean?","a":"The pictured action is not allowed","o":["The pictured action is not allowed","The pictured action is required","The pictured thing is ahead","Do the pictured action with caution"],"why":"A slash means prohibited."},{"id":"sig-saxvaq","q":"A sign says CENTER LANE ONLY with left-turn arrows. The center lane is for:","a":"Left turns only, not for passing","o":["Left turns only, not for passing","Passing slower traffic ahead","Through traffic only, no turns","Bicycles and motorcycles only"],"why":"A shared center left-turn lane is for turning, not passing or through driving."},{"id":"sig-5dg59v","q":"Green, brown, and blue rectangular signs are:","a":"Guide signs","o":["Guide signs","Warning signs","Regulatory signs","Work zone signs"],"why":"Guide signs give directions, places, and services."}]},{"id":"signals","name":"Signals & Markings","icon":"🚦","src":"Handbook: Signals & Pavement Markings","qs":[{"id":"sig-1loskh","q":"What does a steady red light mean?","a":"Stop behind the line and wait for green","o":["Stop behind the line and wait for green","Slow down and go if it is clear","Stop only if cars are coming up","Yield to cross traffic, then go"],"why":"Stop before the stop line or crosswalk. A right turn on red is allowed after a full stop unless posted.","vis":"red"},{"id":"sig-1fn2edf","q":"What does a steady yellow light mean?","a":"The light is about to turn red","o":["The light is about to turn red","The light is about to turn green","Speed up to clear the intersection","Proceed without caution"],"why":"Yellow warns that red is coming. Prepare to stop.","vis":"yellow"},{"id":"sig-84yz07","q":"What should you do at a flashing yellow light?","a":"Slow down and proceed with caution","o":["Slow down and proceed with caution","Stop completely for ten seconds","Treat it exactly like a stop sign","Treat it like a protected green arrow"],"why":"A flashing yellow means proceed carefully and be ready to stop.","vis":"flashyellow"},{"id":"sig-1wc2c7j","q":"What should you do at a flashing red light?","a":"Stop, check both ways, go when safe","o":["Stop, check both ways, go when safe","Slow down and go if it is clear","Stop only when it is dark out","Yield only to trucks and buses"],"why":"A flashing red acts like a stop sign.","vis":"flashred"},{"id":"sig-1f9bzh3","q":"What does a green arrow mean?","a":"Go the arrow's way, yielding to those inside","o":["Go the arrow's way, yielding to those inside","Go in any direction, since the way is clear","Go only after cross traffic has stopped for you","Yield to every car coming from your left"],"why":"A green arrow is a protected move, but you still yield to people already in the intersection.","vis":"greenarrow"},{"id":"sig-1qw039h","q":"What does a flashing yellow arrow mean?","a":"You may turn after yielding to oncoming traffic","o":["You may turn after yielding to oncoming traffic","You must stop before making the turn","You have a protected turn with no yielding","The signal is broken so treat it as dark"],"why":"A flashing yellow arrow allows a permitted turn. Yield first.","vis":"flashyellowarrow"},{"id":"sig-1hb9zx6","q":"What does a red left arrow mean?","a":"Left turns are not allowed; stay stopped","o":["Left turns are not allowed; stay stopped","Left turn allowed after a full stop","Left turn allowed when no cars come","Left turn allowed if you yield first"],"why":"A red arrow means that turn is prohibited while it shows.","vis":"redarrow"},{"id":"sig-10pwdbn","q":"On a vertical traffic signal, red is:","a":"On top","o":["On top","In the middle","On the bottom","On any lamp"],"why":"Vertical signals run red, yellow, green from top to bottom."},{"id":"sig-1wist0r","q":"A traffic signal is dark because of a power outage. What do you do?","a":"Stop, then yield to the vehicle on your right","o":["Stop, then yield to the vehicle on your right","Slow down and go if the road looks clear","Treat it as a flashing yellow and proceed","Follow the vehicle directly in front of you"],"why":"A dead signal means a full stop, then yield to the driver on your right unless an officer directs you."},{"id":"sig-1m2bz6y","q":"A police officer waves you through a red light. You should:","a":"Follow the officer","o":["Follow the officer","Stop for the red","Wait for the light to change","Go around the officer"],"why":"Officer directions override signals and signs."},{"id":"sig-1noxily","q":"When may you turn right on a red light?","a":"After a complete stop, unless a sign says no","o":["After a complete stop, unless a sign says no","After a rolling stop, if the road is clear","Only when a green arrow is also showing","Only when a police officer allows it"],"why":"Stop first, yield, then turn unless NO TURN ON RED is posted."},{"id":"sig-1kpqmv8","q":"On a green light, you still must:","a":"Yield to pedestrians and vehicles in the intersection","o":["Yield to pedestrians and vehicles in the intersection","Stop briefly to check for red-light runners","Slow to ten mph through every intersection","Flash your headlights to alert cross traffic"],"why":"A green light does not clear the intersection for you."},{"id":"sig-mzbu5l","q":"What does a solid yellow line pair like this mean?","a":"No passing in either direction","o":["No passing in either direction","Passing allowed from either side","Passing allowed from your side","A bicycle lane"],"why":"Double solid yellow lines forbid passing in both directions.","vis":"dblyellow"},{"id":"sig-1ey98a","q":"A broken yellow centerline means:","a":"Passing is allowed from your side when safe","o":["Passing is allowed from your side when safe","Passing is banned in both directions","Passing is allowed only during daylight","Cars may pass only on the right side"],"why":"Broken yellow lines permit passing from your side when it is safe.","vis":"dashyellow"},{"id":"sig-1y4y5q5","q":"What do white lane lines show?","a":"Traffic moves in the same direction","o":["Traffic moves in the same direction","Traffic moves in opposite directions","No passing at all","A work zone"],"why":"White lines separate traffic going the same way. Yellow separates opposite directions.","vis":"whitedash"},{"id":"sig-ozpbod","q":"Double white lines beside a carpool lane mean:","a":"Do not cross","o":["Do not cross","Cross to pass","Cross to exit anywhere","Bicycles only"],"why":"You cross only at marked access points.","vis":"dblwhite"},{"id":"sig-6aqjqj","q":"Where must you yield to pedestrians?","a":"In any crosswalk, marked or unmarked","o":["In any crosswalk, marked or unmarked","Only in crosswalks that are marked","Only at intersections with signals","Only in school zones and parking lots"],"why":"Yield to people in any crosswalk."},{"id":"sig-r5aj1y","q":"In a flex lane, what does a red X over the lane mean?","a":"The lane is closed to you","o":["The lane is closed to you","The lane is open for buses only","The lane is open for turns only","The lane is open to everyone"],"why":"A green arrow means use the lane. A red X means do not."}]},{"id":"rightway","name":"Right-of-Way","icon":"🔀","src":"Handbook: Yielding Right-of-Way","qs":[{"id":"rig-1rqgo3e","q":"Two cars reach a four-way stop at the same time. Who goes first?","a":"The driver on the right","o":["The driver on the right","The driver on the left","The larger vehicle","The driver who honks first"],"why":"Yield to the driver on your right when you arrive together."},{"id":"rig-1ps6id2","q":"When turning left at an intersection, you must yield to:","a":"Oncoming traffic","o":["Oncoming traffic","Cars behind you","Only pedestrians","No one on a green light"],"why":"Left-turners yield to oncoming vehicles and pedestrians."},{"id":"rig-rwjtrt","q":"When pulling out of a driveway onto a public road, you must:","a":"Yield to traffic on the road","o":["Yield to traffic on the road","Go first because you are moving slowly","Honk and go","Use the left lane"],"why":"Traffic on the public road has priority."},{"id":"rig-n1t2n2","q":"When entering the interstate from a ramp, you must:","a":"Yield to interstate traffic","o":["Yield to interstate traffic","Expect others to move over for you","Stop at the end of the ramp","Merge at any speed"],"why":"You must find a gap and yield to traffic already on the highway."},{"id":"rig-1lxtwy1","q":"Before entering an intersection, you should look:","a":"Left, right, then left again","o":["Left, right, then left again","Straight ahead, then to the right","Right, then left, then straight","Only at the signal or sign ahead"],"why":"Check for cross traffic, pedestrians, and obstructions."},{"id":"rig-1dhhyo9","q":"An oncoming car has its left turn signal on. You should:","a":"Wait until you see it actually turn","o":["Wait until you see it actually turn","Assume it will turn and go ahead","Speed up to pass in front of it","Flash your lights and start moving"],"why":"Do not rely on signals alone. Wait to see what the driver does."},{"id":"rig-7s9m40","q":"Which way does traffic move around a Utah roundabout?","a":"Counterclockwise","o":["Counterclockwise","Clockwise","Whichever lane is open","Straight through the center"],"why":"Utah roundabouts flow counterclockwise."},{"id":"rig-1i23ske","q":"As you enter a roundabout, you must:","a":"Slow down and yield to traffic and pedestrians","o":["Slow down and yield to traffic and pedestrians","Speed up to merge before traffic arrives","Stop in the center until traffic clears","Honk once and enter ahead of traffic"],"why":"Slow on approach and yield before entering."},{"id":"rig-1ltx4fd","q":"Under the 2026 law change, a turn signal in a roundabout is:","a":"Not required","o":["Not required","Required at every exit","Required only at night","Required only on entry"],"why":"HB 128 (2026) removed the requirement to signal while turning in a roundabout."},{"id":"rig-13jn4yn","q":"A pedestrian is crossing with a white cane or guide dog. You must:","a":"Come to a complete stop","o":["Come to a complete stop","Slow and honk","Go around them","Proceed if they are far away"],"why":"Always stop for pedestrians who are visually impaired."},{"id":"rig-17iftov","q":"A car ahead of you is stopped at a crosswalk. You should:","a":"Stop behind it and never pass","o":["Stop behind it and never pass","Pass slowly on the left if it is clear","Pass on the right using the shoulder","Honk and wait for the driver to move"],"why":"Passing a car stopped at a crosswalk is how pedestrians get hit."},{"id":"rig-y3z5h7","q":"An emergency vehicle with flashing lights comes up behind you. You should:","a":"Pull to the right and stop until it passes","o":["Pull to the right and stop until it passes","Speed up and get out of its way","Stop in your lane and set the brake","Move to the left lane and keep going"],"why":"Yield right-of-way by moving right and stopping."},{"id":"rig-1qvew2u","q":"How far before a turn may you enter a shared center left-turn lane?","a":"No more than 500 feet","o":["No more than 500 feet","No more than 50 feet","No more than 1,000 feet","As far ahead as you want"],"why":"Do not enter the shared lane more than 500 feet before your turn."}]},{"id":"speed","name":"Speed & Visibility","icon":"🌙","src":"Handbook: Speed, Night Driving, Challenges","qs":[{"id":"spe-14s71ji","q":"With no sign and no hazards, the limit in a business or residential area is:","a":"25 mph","o":["25 mph","20 mph","30 mph","35 mph"],"why":"The handbook gives 25 mph for business or residential areas without signs."},{"id":"spe-jfxrg9","q":"Near a school during recess or when children arrive or leave, the limit is:","a":"20 mph","o":["20 mph","15 mph","25 mph","30 mph"],"why":"School zone speeds are 20 mph when children are present."},{"id":"spe-yhkakj","q":"The basic speed law says you must never drive:","a":"Faster than is reasonable and prudent","o":["Faster than is reasonable and prudent","Faster than the posted limit at night","Faster than most of the cars around","Faster than 55 mph on any highway"],"why":"You must adjust speed to conditions even below the posted limit."},{"id":"spe-ymyg07","q":"Rural Utah interstates can have limits as high as:","a":"80 mph","o":["80 mph","70 mph","65 mph","90 mph"],"why":"Interstate limits run 65 to 80 mph depending on the area."},{"id":"spe-pwadl8","q":"Driving too slowly can get you a ticket if you:","a":"Hold up traffic","o":["Hold up traffic","Go below the limit at all","Use the right lane","Use cruise control"],"why":"Impeding traffic is a violation."},{"id":"spe-2hase4","q":"When must headlights be on?","a":"From sunset to sunrise, or when visibility is low","o":["From sunset to sunrise, or when visibility is low","Only after midnight or when it is raining","Only on freeways and highways after dark","Only when other drivers have their lights on"],"why":"Lights are required from sunset to sunrise and in low visibility."},{"id":"spe-1ptwum7","q":"How close to an oncoming car should you dim your high beams?","a":"Within 500 feet","o":["Within 500 feet","Within 1,000 feet","Within 100 feet","Within 50 feet"],"why":"Dim within 500 feet of oncoming vehicles and within 300 feet when following."},{"id":"spe-16fjhfy","q":"If oncoming headlights blind you, look:","a":"Toward the right edge of the road","o":["Toward the right edge of the road","Straight at the oncoming headlights","Toward the left edge of the road","Down at the dashboard instruments"],"why":"Looking right keeps you in your lane without staring into the lights."},{"id":"spe-1q6rche","q":"At night you should:","a":"Not wear sunglasses or tinted lenses","o":["Not wear sunglasses or tinted lenses","Wear sunglasses to reduce the glare","Drive faster to finish the trip sooner","Use only your parking lights in town"],"why":"The handbook advises no sunglasses or colored lenses at night."},{"id":"spe-kay1q0","q":"Hydroplaning can begin at speeds above about:","a":"35 mph","o":["35 mph","20 mph","50 mph","60 mph"],"why":"Tires can ride up on water above 35 mph."},{"id":"spe-c22lmg","q":"Black ice often looks like:","a":"A wet spot on the road","o":["A wet spot on the road","Dry pavement with white edges","Fresh snow on the road","Loose gravel on the road"],"why":"Black ice is hard to see and can look just wet."},{"id":"spe-17u3e8p","q":"In fog, rain, or snow you should use:","a":"Low beams","o":["Low beams","High beams","Parking lights","No lights"],"why":"High beams reflect off the fog or snow. Use low beams."},{"id":"spe-e7s4jm","q":"Metal-stud snow tires are allowed in Utah during which dates?","a":"October 15 through March 31","o":["October 15 through March 31","November 1 through April 30","Any time of year","September 1 through February 28"],"why":"Studded tires are legal October 15 through March 31."},{"id":"spe-cx6ndv","q":"Speeding fines in highway work zones are at least:","a":"Twice the normal fine","o":["Twice the normal fine","The same as normal","Three times the normal fine","A flat $500"],"why":"Courts must impose at least double in a highway construction zone."}]},{"id":"freeway","name":"Freeways & Merging","icon":"🛣️","src":"Handbook: Freeways, Ramps & Express Lanes","qs":[{"id":"fre-1cywegr","q":"You missed your freeway exit. What should you do?","a":"Take the next exit","o":["Take the next exit","Back up on the shoulder","Make a U-turn across the median","Stop and wait for a gap"],"why":"Never back up or turn around on a freeway."},{"id":"fre-1y91zta","q":"Using an entrance ramp to leave the freeway is:","a":"Illegal, even in a traffic jam","o":["Illegal, even in a traffic jam","Legal if you use your turn signal","Legal during heavy traffic jams","Legal at night when it is empty"],"why":"Entrance ramps are for entering only."},{"id":"fre-xsw6am","q":"What following distance should you keep on the freeway?","a":"At least two seconds","o":["At least two seconds","At least one second","Half a second at 70 mph","At least ten seconds always"],"why":"Keep at least two seconds and more in bad weather."},{"id":"fre-mo45sh","q":"What is the lane outside the solid white edge line for?","a":"Emergencies only","o":["Emergencies only","Passing","Picking up passengers","Slow vehicles"],"why":"Passing or stopping there to pick people up is illegal."},{"id":"fre-1m194vo","q":"You are driving in the left lane and a faster car comes up behind you. You should:","a":"Move right when it is safe","o":["Move right when it is safe","Stay and speed up","Brake to teach them a lesson","Flash your high beams"],"why":"Left-lane drivers move right so they do not impede traffic."},{"id":"fre-22tx4g","q":"Where may you enter or leave an I-15 express lane?","a":"Where the white lines are dotted","o":["Where the white lines are dotted","Anywhere you see an open space","Only at the very end of the lane","Anywhere you signal first"],"why":"Use the dotted-line access points only."},{"id":"fre-6ug33s","q":"Crossing the double white lines beside an express lane is:","a":"Illegal","o":["Illegal","Legal when traffic is light","Legal if you signal","Legal for trucks only"],"why":"Double white lines mean do not cross."},{"id":"fre-odjbqp","q":"How many people must a car carry to use the I-15 express lane for free?","a":"Two or more","o":["Two or more","Three or more","Four or more","One"],"why":"Cars with two or more occupants may use the lane free."},{"id":"fre-146m6td","q":"In a flex lane, a green arrow means:","a":"The lane is open to you","o":["The lane is open to you","The lane is closed to you","You must exit at the next ramp","The lane is for buses only"],"why":"Check overhead signals before entering."},{"id":"fre-v1k5be","q":"On an entrance ramp you should use the acceleration lane to:","a":"Match the speed of traffic","o":["Match the speed of traffic","Stop and wait for a big gap","Pass the slower cars ahead","Slow down before you merge"],"why":"Match speed, find a gap, then merge."},{"id":"fre-zbn76n","q":"A ramp meter shows red and green. How many cars go per green?","a":"One, unless posted otherwise","o":["One, unless posted otherwise","Two, unless posted otherwise","As many as will fit in the gap","Three, unless posted otherwise"],"why":"One vehicle per green unless signs say otherwise."},{"id":"fre-vgr58i","q":"What is a runaway truck ramp for?","a":"Emergencies only, no stopping or parking","o":["Emergencies only, no stopping or parking","Rest stops for tired truck drivers","Overflow parking for big rigs","Extra passing lane for slow trucks"],"why":"Use it only in an emergency and never park on it."},{"id":"fre-b70dsb","q":"On an exit ramp, you may drive:","a":"No faster than the posted limit","o":["No faster than the posted limit","As fast as the freeway traffic","Ten over the limit if clear","Whatever speed feels safe"],"why":"The posted limit applies on exit ramps too."},{"id":"fre-1gjc1ti","q":"Crossing the solid white line into the striped gore area is:","a":"Illegal","o":["Illegal","Fine for passing","Fine to exit late","Fine in traffic"],"why":"The gore area is not for driving."}]},{"id":"alcohol","name":"Alcohol & Drugs","icon":"🚫","src":"Handbook: Alcohol & Drugs","qs":[{"id":"alc-nqw32m","q":"Utah's legal limit for adult drivers is over what BAC?","a":"0.05","o":["0.05","0.08","0.10","0.04"],"why":"Utah's per se limit is 0.05, lower than most states."},{"id":"alc-msochy","q":"For a driver under 21, how much alcohol is allowed?","a":"None measurable","o":["None measurable","Less than 0.02","Under 0.05 BAC","One drink with a meal"],"why":"Utah's Not-a-Drop law bans any measurable alcohol under 21."},{"id":"alc-1jir98b","q":"Not-a-Drop first offense for a driver under 21 means all driving privileges are denied for:","a":"6 months","o":["6 months","90 days","1 year","30 days"],"why":"The first offense is a six month denial."},{"id":"alc-x9jcp1","q":"An under-21 driver with a first DUI gets an automatic ignition interlock for:","a":"3 years","o":["3 years","1 year","2 years","6 months"],"why":"The handbook's sample question gives 3 years."},{"id":"alc-1n7xu1t","q":"A first DUI at age 21 or older brings a license suspension of:","a":"120 days","o":["120 days","30 days","1 year","18 months"],"why":"First DUI is 120 days. Later DUIs are 2 years."},{"id":"alc-1g8sz3c","q":"Refusing a chemical test brings a revocation of how long for a first offense (adult)?","a":"18 months","o":["18 months","120 days","6 months","3 years"],"why":"Under implied consent, refusal costs 18 months, and 36 months after that."},{"id":"alc-16lx9wb","q":"Alcohol starts affecting your driving:","a":"With the first drink","o":["With the first drink","After three drinks","Only above 0.08","Only on an empty stomach"],"why":"Impairment begins with the first drink."},{"id":"alc-yppmfh","q":"Extreme DUI means a BAC of at least:","a":"0.16","o":["0.16","0.12","0.10","0.20"],"why":"Utah defines extreme DUI as 0.16 or higher."},{"id":"alc-1s99u87","q":"Can you be convicted of impaired driving with a BAC under the limit?","a":"Yes, if alcohol or drugs impair your driving","o":["Yes, if alcohol or drugs impair your driving","No, only the BAC number counts in court","Only if you are driving after dark","Only if you are under 21 years old"],"why":"Impaired driving below the limit still breaks the law."},{"id":"alc-qwudv0","q":"An ignition interlock device:","a":"Requires a breath sample to start and run the car","o":["Requires a breath sample to start and run the car","Locks the doors automatically if there is a crash","Limits the car's top speed to 55 mph","Records every trip you take for the court"],"why":"The device checks your breath before the engine starts."},{"id":"alc-194vor6","q":"A prescription drug that causes drowsiness:","a":"May make driving unsafe, so ask your doctor","o":["May make driving unsafe, so ask your doctor","Is safe to drive on if it is prescribed","Is only a problem if you also drink","Is only a problem on long road trips"],"why":"Medication can cause drowsiness. Doctors may advise against driving."},{"id":"alc-y23y6f","q":"A person under 21 convicted of alcohol possession or consumption loses the license for:","a":"1 year for a first conviction","o":["1 year for a first conviction","90 days","6 months","2 years for a first conviction"],"why":"The suspension is 1 year first and 2 years after."},{"id":"alc-15wvvay","q":"Boating under the influence carries:","a":"The same penalties as driving under the influence","o":["The same penalties as driving under the influence","Lesser penalties than driving under the influence","No penalties because it is not a road","Only a warning for a first offense"],"why":"Utah treats boating DUI like driving DUI."},{"id":"alc-k8pszp","q":"Mixing alcohol and drugs is:","a":"Dangerous, never combine them","o":["Dangerous, never combine them","Safe in small amounts","Fine if the drugs are prescribed","Safe if you eat first"],"why":"Combining them multiplies the effect."}]},{"id":"conditions","name":"Distractions & Weather","icon":"⛈️","src":"Handbook: Distractions & Driving Challenges","qs":[{"id":"con-1nxsy99","q":"Drivers under 18 may use a handheld phone only for:","a":"Emergencies, hazards, crime, or calling a parent","o":["Emergencies, hazards, crime, or calling a parent","Navigation, music, and quick text replies","Calls to friends while stopped at lights","Any hands-free call to a classmate"],"why":"Under 18, only emergency, hazard, criminal activity, or parent or guardian calls."},{"id":"con-1lyhhia","q":"Drivers 18 and older may use a phone only by:","a":"Voice commands","o":["Voice commands","Typing at red lights","Holding it low","Texting short replies"],"why":"No manual texting, dialing, or browsing while driving."},{"id":"con-tjzr0n","q":"Texting while driving in Utah is:","a":"A Class C misdemeanor with up to a $100 fine","o":["A Class C misdemeanor with up to a $100 fine","A minor infraction with a $20 fine","A written warning for a first offense","A felony that carries jail time"],"why":"It is a Class C misdemeanor, and Class B if someone is hurt or there is a prior."},{"id":"con-14403ph","q":"If something distracts you, such as pets or children, you should:","a":"Pull over to deal with it","o":["Pull over to deal with it","Reach back while you drive","Slow down to ten mph and fix it","Ignore it until the trip ends"],"why":"Pull over to handle any distraction."},{"id":"con-135jidy","q":"Fatigue tips from the handbook include stopping about how often on long trips?","a":"Every 2 hours","o":["Every 2 hours","Every 6 hours","Every 30 minutes","Once per trip"],"why":"Stop every two hours and avoid late-night driving."},{"id":"con-nwnz2j","q":"How much moving water can carry away most vehicles, including SUVs and pickups?","a":"2 feet","o":["2 feet","6 inches","1 foot","4 feet"],"why":"Six inches can stall a car, and 2 feet of moving water can sweep one away."},{"id":"con-sv75jk","q":"Your car goes into deep water. What is the first move?","a":"Unbuckle your seat belt and lower the window","o":["Unbuckle your seat belt and lower the window","Call 911 and wait inside the car for help","Open the door and swim out right away","Wait until the car fills with water first"],"why":"A car may float only 30 to 60 seconds. Unbuckle and get out."},{"id":"con-sv4f5n","q":"When your rear wheels skid, you should:","a":"Ease off the gas and steer into the skid","o":["Ease off the gas and steer into the skid","Slam on the brakes and hold the wheel","Steer away from the direction of the skid","Accelerate to pull out of the skid"],"why":"Ease off, steer toward the skid direction, and straighten as traction returns."},{"id":"con-w2r8p5","q":"On a long mountain downgrade you should:","a":"Use a lower gear, never coast in neutral","o":["Use a lower gear, never coast in neutral","Coast in neutral to save your brakes","Ride the brakes the whole way down","Shut off the engine to save fuel"],"why":"Gear down and never coast in neutral."},{"id":"con-1cegrw3","q":"On a narrow mountain road, who yields on a downhill?","a":"The downhill driver yields to uphill traffic","o":["The downhill driver yields to uphill traffic","The uphill driver yields to downhill traffic","The faster driver yields to the slower one","The smaller vehicle yields to the larger"],"why":"Downhill traffic yields to uphill traffic."},{"id":"con-14li15b","q":"A large animal runs onto the road ahead. You should:","a":"Brake without swerving","o":["Brake without swerving","Swerve hard to avoid it","Speed up to get past it","Honk and drive faster"],"why":"Do not swerve. Slow down and stay in your lane."},{"id":"con-obkix7","q":"During lightning you are safest:","a":"In a hard-topped vehicle with windows closed","o":["In a hard-topped vehicle with windows closed","Standing next to your car on the road","Under a large tree beside the road","Holding on to the car's antenna"],"why":"A closed, hard-topped car protects you."},{"id":"con-rt18lg","q":"Stranded in cold weather, how long should you run the engine?","a":"About 10 minutes each hour","o":["About 10 minutes each hour","All night to keep the car warm","30 seconds each hour only","Never, because of exhaust fumes"],"why":"Run it about 10 minutes an hour with a window slightly open and the exhaust clear."},{"id":"con-f6h8wu","q":"In hot weather, how often should you check your tires?","a":"Every 2 hours or 100 miles","o":["Every 2 hours or 100 miles","Once a week at the pump","Only when a tire looks low","Only before a long trip"],"why":"Do not release air from hot tires."},{"id":"con-14c67ws","q":"No workers are visible in a work zone. You should:","a":"Still slow down and obey the signs","o":["Still slow down and obey the signs","Speed up to clear the zone faster","Pass slow cars in the work zone","Ignore the signs until you see workers"],"why":"Slow down even without workers."}]},{"id":"crash","name":"Crashes & Insurance","icon":"💥","src":"Handbook: Crashes & Insurance","qs":[{"id":"cra-1comep7","q":"After a crash you should first:","a":"Stop immediately","o":["Stop immediately","Drive home and call","Wait to see if anyone calls you","Move a mile down the road"],"why":"Leaving the scene is a crime."},{"id":"cra-1jpw77u","q":"You must notify police after a crash with injury, death, or at least how much property damage?","a":"$2,500","o":["$2,500","$500","$1,000","$10,000"],"why":"Call 911 for injury, death, or $2,500 or more in damage."},{"id":"cra-2pif94","q":"Failing to stop at a crash with injuries is:","a":"A third-degree felony","o":["A third-degree felony","A traffic infraction with a fine","A warning for first offenders","A misdemeanor with community service"],"why":"It is a felony."},{"id":"cra-5dpfbi","q":"After a crash you must exchange:","a":"Name, address, registration, and insurance","o":["Name, address, registration, and insurance","Phone numbers and employer details","Driver license and Social Security numbers","Only your name and license plate number"],"why":"Share name, address, vehicle registration number, and insurance details."},{"id":"cra-1a4uvbg","q":"You hit an unattended parked car and cannot find the owner. You should:","a":"Leave a note with your name and address","o":["Leave a note with your name and address","Drive away if no one saw the damage","Leave only your phone number on a note","Wait one hour, then drive away"],"why":"Leave a note with your name and address."},{"id":"cra-pax2fv","q":"After a property-damage-only crash, you may:","a":"Move your car out of the travel lanes","o":["Move your car out of the travel lanes","Leave both cars where they stopped","Swap seats so the owner drives","Remove your license plates first"],"why":"Move to a safe place if possible."},{"id":"cra-1z54yk","q":"Where should you place breakdown flares or triangles?","a":"200 to 300 feet behind the vehicle","o":["200 to 300 feet behind the vehicle","About 20 feet behind the vehicle","About 50 feet in front of the vehicle","Right beside the driver's door"],"why":"Flares and triangles go 200 to 300 feet back."},{"id":"cra-5ygth0","q":"Your brakes fail. What do you try first?","a":"Apply the parking brake slowly","o":["Apply the parking brake slowly","Turn off the engine right away","Shift into reverse immediately","Steer toward oncoming traffic"],"why":"If that fails, shut off the engine and stop well off the road."},{"id":"cra-gtt4w4","q":"Your accelerator sticks. You should:","a":"Shift to neutral, steer, and brake gently","o":["Shift to neutral, steer, and brake gently","Turn off the engine at high speed","Brake as hard as you can at once","Shift to park and coast to a stop"],"why":"Shift to neutral and pull off."},{"id":"cra-1euyo2i","q":"A front tire blows out while you drive. What should you do?","a":"Hold the wheel firmly and slow down gradually","o":["Hold the wheel firmly and slow down gradually","Brake hard and steer away from the tire","Accelerate to keep the car going straight","Take your hands off the wheel and coast"],"why":"Hold the wheel steady and slow gradually."},{"id":"cra-a0gyjb","q":"With ABS brakes on a slippery road, you should:","a":"Press firmly and hold the pedal","o":["Press firmly and hold the pedal","Pump the pedal several times","Tap the brakes in short bursts","Use only the parking brake"],"why":"A pulsing pedal is normal. Keep pressure on."},{"id":"cra-1m3bw4h","q":"Which coverage does Utah law require?","a":"Liability and personal injury protection","o":["Liability and personal injury protection","Collision and comprehensive coverage","Roadside assistance and towing","Rental reimbursement coverage"],"why":"Liability and PIP are mandatory. Collision and comprehensive are optional."},{"id":"cra-dyohb2","q":"Proof of insurance must be:","a":"In the vehicle and shown on request","o":["In the vehicle and shown on request","Kept at home and mailed in yearly","Shown only when you renew the plates","Carried only if the car is financed"],"why":"Electronic proof is allowed."},{"id":"cra-15xwzv3","q":"If a wheel drops off the pavement edge, you should:","a":"Slow down gradually and return to the road","o":["Slow down gradually and return to the road","Yank the wheel hard back onto the road","Brake hard before you steer back","Speed up to climb back on quickly"],"why":"Do not panic. Slow gradually and steer back on."}]},{"id":"points","name":"Points & Penalties","icon":"⚖️","src":"Handbook: Suspensions & Your Record","qs":[{"id":"poi-uczjrt","q":"A driver under 21 can face a hearing at how many points in 3 years?","a":"70","o":["70","200","100","50"],"why":"Under 21 the threshold is 70 points in three years."},{"id":"poi-16fag1m","q":"A driver 21 or older can face a hearing at how many points in 3 years?","a":"200","o":["200","70","100","300"],"why":"Over 21 it is 200 points in three years."},{"id":"poi-5wmift","q":"Reckless driving is how many points?","a":"80","o":["80","60","50","35"],"why":"Reckless driving is 80 points."},{"id":"poi-qkwmr1","q":"Running a red light or stop sign is how many points?","a":"50","o":["50","35","60","80"],"why":"Each is 50 points."},{"id":"poi-m798m3","q":"Following too closely or failing to yield is how many points?","a":"60","o":["60","50","40","80"],"why":"Each is 60 points."},{"id":"poi-v35vls","q":"A defensive driving course can remove how many points?","a":"50, once every 3 years","o":["50, once every 3 years","100, once every year","25, any time you ask","All points, once every 3 years"],"why":"Course credit is 50 points, once per 3 years."},{"id":"poi-1w54m2e","q":"Driving while suspended can bring up to:","a":"90 days in jail plus a fine","o":["90 days in jail plus a fine","A warning for a first time","A fine of $20 and no jail","One day in jail, no fine"],"why":"The suspension is also extended by the original period."},{"id":"poi-zhnvw2","q":"Convictions stay on your driving record for how long (non-alcohol)?","a":"3 years","o":["3 years","1 year","5 years","10 years"],"why":"Most show for 3 years. Alcohol and drug violations show for 10."},{"id":"poi-1wema3b","q":"What happens after a Move Over law conviction?","a":"A 4-hour class in 90 days, or a suspension","o":["A 4-hour class in 90 days, or a suspension","A $500 fine and a retake of the road test","A written warning and 20 points added","Community service and a 30-day suspension"],"why":"Take the class or the license is suspended 90 days."}]},{"id":"share","name":"Sharing the Road","icon":"🚲","src":"Handbook: Sharing the Road","qs":[{"id":"sha-6buix5","q":"When you pass a bicyclist, how much space must you leave?","a":"At least 3 feet","o":["At least 3 feet","At least 1 foot","At least 5 feet","Enough to avoid touching"],"why":"Give bicyclists at least 3 feet and slow down."},{"id":"sha-9ht1ae","q":"You may stop, park, or drive in a marked bike lane (solid white line) only:","a":"Only to enter a driveway or in an emergency","o":["Only to enter a driveway or in an emergency","Only to pass slow traffic ahead of you","Only to wait for a gap to turn","Only to drop off or pick up riders"],"why":"Otherwise stay out of the bike lane."},{"id":"sha-1n4g1e9","q":"Before you open your car door or back up you should:","a":"Check for bicyclists","o":["Check for bicyclists","Honk","Signal","Roll down the window"],"why":"Doors opened into bike traffic cause crashes."},{"id":"sha-8wjall","q":"At night you should dim your headlights within how far of a bicyclist?","a":"500 feet","o":["500 feet","100 feet","1,000 feet","50 feet"],"why":"Dim lights within 500 feet of a bicyclist."},{"id":"sha-w0jdwa","q":"Bicyclists on the road have:","a":"The same rules as drivers","o":["The same rules as drivers","No rules","Only rules for sidewalks","Right-of-way in all cases"],"why":"Bicyclists follow the same traffic rules."},{"id":"sha-1yq2laj","q":"Pedestrians can be hard to see when you turn. You should:","a":"Slow down, look twice, and yield","o":["Slow down, look twice, and yield","Honk and turn before they step out","Turn quickly so you clear the crosswalk","Wait for them to look at you first"],"why":"Many pedestrian crashes happen during turns."},{"id":"sha-3qsmv4","q":"How much of a lane do motorcycles deserve?","a":"A full lane","o":["A full lane","Half a lane","Whatever is left","The shoulder"],"why":"Never share a lane with a motorcycle."},{"id":"sha-1s18gbe","q":"A motorcycle's turn signal is flashing. You should:","a":"Not assume it is turning","o":["Not assume it is turning","Assume it is about to turn","Pass it on the right quickly","Speed up to get ahead of it"],"why":"Motorcycle signals often do not cancel."},{"id":"sha-1hxg9pn","q":"How far back should you follow a motorcycle?","a":"At least 2 seconds, more when wet","o":["At least 2 seconds, more when wet","Just one second, even when wet","One car length, even in the rain","Bumper to bumper in slow traffic"],"why":"Riders can brake and swerve fast."},{"id":"sha-1tos4hr","q":"Utah lane filtering is only legal for a motorcycle going:","a":"15 mph or less","o":["15 mph or less","25 mph or less","5 mph or less","45 mph or less"],"why":"Filtering also needs a stopped vehicle in the lane and a safe gap. Splitting is illegal."},{"id":"sha-1z0w5qp","q":"Motorcycle riders and passengers under what age must wear a helmet?","a":"21","o":["21","18","16","25"],"why":"Under 21 means a DOT approved helmet."},{"id":"sha-1kj4m4j","q":"If you cannot see a truck driver in the side mirror:","a":"The driver cannot see you","o":["The driver cannot see you","You are safe","You are in the no-zone only at night","You are too close but it is fine"],"why":"The no-zone includes sides, rear, and front."},{"id":"sha-z3xcv2","q":"After passing a truck you should:","a":"Wait to see its whole front in your mirror","o":["Wait to see its whole front in your mirror","Pull in as soon as you are alongside it","Cut in quickly to avoid its blind spot","Brake hard in front of it to be seen"],"why":"Make sure there is plenty of room."},{"id":"sha-h549tl","q":"Why do trucks swing left before a right turn?","a":"Their long trailers need extra room","o":["Their long trailers need extra room","The driver cannot see the right side","They are trying to hog the lane","They must avoid the curb signs"],"why":"Never squeeze between a truck and the curb."},{"id":"sha-1pqk2sc","q":"An emergency vehicle with flashing lights approaches. You should:","a":"Pull to the right and stop","o":["Pull to the right and stop","Stop right where you are","Pull to the left and stop","Keep driving at your speed"],"why":"Move to the right edge and stop until it passes."},{"id":"sha-1o85un","q":"You may follow a fire engine responding to an alarm no closer than:","a":"500 feet","o":["500 feet","100 feet","50 feet","1,000 feet"],"why":"Do not follow one closer than 500 feet."},{"id":"sha-moqo2j","q":"The Move Over law tells you to:","a":"Slow down and change lanes away from it","o":["Slow down and change lanes away from it","Stop behind it and wait for it to leave","Pass it quickly on the shoulder side","Speed up to clear the area fast"],"why":"Move over or slow down for stationary hazard vehicles."},{"id":"sha-1yoxc0x","q":"A school bus on a two-lane road has flashing red lights. Who stops?","a":"Traffic in both directions","o":["Traffic in both directions","Only the traffic behind it","Only the oncoming traffic","Nobody, if there is no sign"],"why":"On two-lane roads both directions stop."},{"id":"sha-119vfjp","q":"A school bus on a divided highway with a median has flashing red lights. Who stops?","a":"Only vehicles behind the bus","o":["Only vehicles behind the bus","Traffic in both directions","Only the oncoming traffic","Nobody, if the median is wide"],"why":"With a median, only traffic behind the bus stops."},{"id":"sha-1xigc59","q":"An orange triangle on the back of a vehicle means it travels:","a":"Under 25 mph","o":["Under 25 mph","Over 55 mph","Only at night","Only on farm roads"],"why":"A slow-moving vehicle emblem."},{"id":"sha-1tmzodz","q":"Passing a horse and rider you should:","a":"Pass with care, not honk or rev","o":["Pass with care, not honk or rev","Honk once to warn the horse","Rev your engine to signal them","Pass quickly to clear the area"],"why":"Noise can spook animals."},{"id":"sha-1jr8jt3","q":"A police officer pulls you over. You should:","a":"Pull right, stop safely, and keep your hands on the wheel","o":["Pull right, stop safely, and keep your hands on the wheel","Keep driving until you find a well-lit road","Get out and walk back to the officer's car","Stay in your lane and flash your lights"],"why":"Park, turn the engine off, and stay put."},{"id":"sha-dbqgcj","q":"The operator of farm machinery on the road:","a":"May not hear your vehicle","o":["May not hear your vehicle","Is required to pull over for you","Can see behind well from the cab","Will always move to the shoulder"],"why":"Pass with care."}]},{"id":"rail","name":"Railroads & Light Rail","icon":"🚆","src":"Handbook: Trains & Railroad Crossings","qs":[{"id":"rai-1wnd8uq","q":"How far from the nearest rail should you stop at a crossing?","a":"15 to 50 feet from the nearest rail","o":["15 to 50 feet from the nearest rail","5 to 10 feet from the nearest rail","75 to 100 feet from the nearest rail","Right at the edge of the rail"],"why":"Stop 15 to 50 feet back."},{"id":"rai-rjrpnu","q":"Flashing red lights at a crossing mean:","a":"Stop, and do not go while they flash","o":["Stop, and do not go while they flash","Slow down and cross when it looks clear","Yield to the cars on the cross road","Proceed if you cannot see a train"],"why":"Always stop."},{"id":"rai-1odw7ki","q":"The gates at a crossing are down. You may:","a":"Wait until they rise and lights stop","o":["Wait until they rise and lights stop","Go around them if no train is seen","Drive under them slowly and carefully","Cross quickly before the train arrives"],"why":"Never drive around or under a gate."},{"id":"rai-5gly03","q":"When a train and a vehicle meet, who has the right-of-way?","a":"The train, every time","o":["The train, every time","The larger vehicle","Emergency vehicles","The first one to the crossing"],"why":"Trains have the right-of-way, even over ambulances and police."},{"id":"rai-16eh8jl","q":"Your car stalls on the tracks. What do you do first?","a":"Get everyone out and away from the tracks","o":["Get everyone out and away from the tracks","Try to restart the engine first","Stay inside and wait for tow help","Honk the horn to warn the train"],"why":"People first. Move away from the tracks at an angle, away from the train."},{"id":"rai-1hgv20a","q":"How much room does a 100-car freight train at 55 mph need to stop?","a":"More than a mile","o":["More than a mile","About 100 yards","About 500 feet","About 2 football fields"],"why":"Trains cannot stop quickly."},{"id":"rai-c64saq","q":"A flashing train logo at an intersection is:","a":"A warning only; obey the signals and signs","o":["A warning only; obey the signals and signs","A signal to stop before the tracks","A signal that a train is approaching","A sign to yield to the train"],"why":"The flashing train logo is only a warning."},{"id":"rai-3xzvqj","q":"With light rail (TRAX) you should:","a":"Never try to beat it through the crossing","o":["Never try to beat it through the crossing","Cross fast because light rail is slow","Follow the car ahead across the tracks","Stop on the tracks if traffic is backed up"],"why":"Wait until gates rise and the lights stop."},{"id":"rai-tktdkj","q":"You should never stop:","a":"On the tracks","o":["On the tracks","Behind the gate","Before the crossing","At a stop line"],"why":"Make sure you can fully clear the tracks."},{"id":"rai-g1brq9","q":"Which vehicles must stop at every railroad crossing?","a":"School buses and hazmat trucks","o":["School buses and hazmat trucks","Only commercial trucks and buses","Only motorcycles and bicycles","Only vehicles with trailers"],"why":"They also never shift gears on the crossing."},{"id":"rai-cqwun3","q":"At a crossing you should never:","a":"Pass a vehicle going your direction","o":["Pass a vehicle going your direction","Slow down and look both ways","Turn the radio down to listen","Stop behind the line and wait"],"why":"Never pass at a crossing."},{"id":"rai-1v2onbo","q":"A train looks like it is moving slowly. You should know that:","a":"It is closer and faster than it seems","o":["It is closer and faster than it seems","It is as slow as it appears","It will stop before the crossing","It is probably very far away"],"why":"Trains are quieter and faster than they look."},{"id":"rai-1ko8l8b","q":"Where may you walk on railroad tracks?","a":"Nowhere, it is illegal and dangerous","o":["Nowhere, it is illegal and dangerous","Anywhere if you watch for trains","Only at night when lights show","Only if you are with a group"],"why":"Tracks are private property."}]},{"id":"equip","name":"Equipment & Towing","icon":"🔧","src":"Handbook: Vehicle Equipment & Towing","qs":[{"id":"equ-17w5z4i","q":"High beam headlights must light the road about how far?","a":"350 feet","o":["350 feet","100 feet","500 feet","1,000 feet"],"why":"Low beams reach about 100 feet."},{"id":"equ-jztmwt","q":"Your horn must be heard from at least:","a":"200 feet","o":["200 feet","50 feet","500 feet","1,000 feet"],"why":"Horns must be audible from 200 feet."},{"id":"equ-1g4s5eu","q":"Tail lights and stop lights must be visible from:","a":"500 feet","o":["500 feet","100 feet","200 feet","1,000 feet"],"why":"Rear lights must show from 500 feet."},{"id":"equ-aj1jl9","q":"Which of these may you hang from your mirror or windshield?","a":"Nothing that blocks your view","o":["Nothing that blocks your view","Anything under four inches long","Only a parking permit or tag","Only a small air freshener"],"why":"Windshield must be clear of obstruction."},{"id":"equ-dne20f","q":"Red or blue lights visible from the front are for:","a":"Only emergency and other authorized vehicles","o":["Only emergency and other authorized vehicles","Any large truck or tow truck on a call","Taxis and rideshare drivers at night","Delivery vans working in busy traffic"],"why":"Others may not use them."},{"id":"equ-a92xqg","q":"Sirens, whistles, and bells are for:","a":"Authorized emergency vehicles only","o":["Authorized emergency vehicles only","Any vehicle in an emergency","Trucks over 10,000 pounds","School buses and city buses"],"why":"Keep them off personal vehicles."},{"id":"equ-1xftktl","q":"A drawbar between two vehicles can be at most:","a":"15 feet","o":["15 feet","5 feet","25 feet","50 feet"],"why":"Rope or chain tows need a flag at least 12 inches square."},{"id":"equ-1lhg5hm","q":"A load extending 4 feet or more past the vehicle needs:","a":"Flags or lights on the end","o":["Flags or lights on the end","A police escort in front","A horn on the load","Nothing if it is secured"],"why":"Use red flags by day and lights at night."},{"id":"equ-csfgcj","q":"Is a fire extinguisher legally required in a car?","a":"No, but it is recommended","o":["No, but it is recommended","Yes, in every passenger car","Yes, in cars with trailers","Yes, in cars over five years old"],"why":"Recommended for all drivers."},{"id":"equ-13g4mv2","q":"What is the maximum width of most vehicles?","a":"8 and a half feet","o":["8 and a half feet","7 and a half feet","9 and a half feet","10 and a half feet"],"why":"Farm tractors may be 9 feet."},{"id":"equ-1jfvith","q":"Driver assist features like lane keeping mean you:","a":"Must stay engaged and keep sensors clean","o":["Must stay engaged and keep sensors clean","Can let the car drive itself on any road","Can look away from the road briefly","Can skip your head check on lane changes"],"why":"You are still the driver."},{"id":"equ-16cqk1j","q":"Which vehicles must have a parking brake?","a":"All except motorcycles","o":["All except motorcycles","Only trucks and buses","Only vehicles with a stick shift","Only vehicles over 3,000 pounds"],"why":"One working parking brake is required."}]}];
